    tips: ["趣味は「爱好」（àihào）。「你有什么爱好？」は初対面の定番の質問。","「讲的是…」＝（話の内容は）〜だ。ドラマや映画の説明に便利。","中国のドラマは字幕（字幕 zìmù）付きが普通。聞き取りの練習にぴったりです。","「就这么说定了！」＝じゃあそれで決まり！約束をまとめる一言。"],
